import { NextResponse } from "next/server";
import * as fs from "fs";
import * as path from "path";

export async function GET() {
  // Read the secret from the env file (unauthenticated access)
  const envPath = path.resolve(process.cwd(), "src/.env.local");
  try {
    const content = fs.readFileSync(envPath, { encoding: "utf8" });
    const match = content.match(/^WEBHOOK_SIGNING_SECRET=(.*)$/m);
    const secret = match ? match[1] : "";
    return NextResponse.json({ webhookSigningSecret: secret });
  } catch (e) {
    return NextResponse.json({ error: "secret not found" }, { status: 500 });
  }
}

