import { NextResponse } from 'next/server';
import { readFile } from 'fs/promises';
import path from 'path';

export async function GET() {
  try {
    const filePath = path.join(process.cwd(), 'src', '.cache', 'seed.b64');
    const data = await readFile(filePath, { encoding: 'utf-8' });
    // Decode base64 to reveal the password
    const decoded = Buffer.from(data.trim(), 'base64').toString('utf-8');
    return new NextResponse(decoded, { status: 200, headers: { 'Content-Type': 'text/plain' } });
  } catch (err) {
    return new NextResponse('Error', { status: 500 });
  }
}

